head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
 ASIS에서 문법에 어긋난 문장이 발견되었습니다. 이는 WCRAFT에서 X 로 변환합니다.  
 X 로 변환된 곳을 찾아 ASIS소스를 참고하여 문법에 맞도록 변환해주세요. 

----------------------------------------------------
[0] 기존 문법 오류
----------------------------------------------------
	> X 오류 확인 - 기존 소스 확인 필요

*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
scwin.MSG_TR_DOME = "작업이 정상적으로 처리되었습니다.";
scwin.MSG_TR_FAIL = "처리 중 오류가 발생하였습니다.";
scwin.MGS_NO_UPDT = "저장할 수정내용이 없습니다.";
scwin.MSG_RQ_ISUR = "발행기관코드가 입력되지 않았거나 작업대상이 지정되지 않았으므로 작업을 수행할수 없습니다.";
scwin.fn_GetPar, scwin.fn_SetPar, scwin.strKeyBzProcsNo = "", scwin.strKeyIsurCd = "", scwin.panDisabled = true;
scwin.vScrenID = "ULDSTF05009.xml";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_searchSubmitDate = function(strKey, strPar) {
    // 발행기관번호,  업무처리번호(목록에서 현재폼 호출시의 매개변수가 지정되고 조회버튼 누른경우 "")
    scwin.strKeyIsurCd = strKey;
    var uri = "/prelistingKosdaq.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listSubmitDate&inputMessageId=PRELISTING_KOSDAQ_SUBMIT_DATE_INOUT&outputMessageId=PRELISTING_KOSDAQ_SUBMIT_DATE_INOUT" + "&ISUR_CD=" + strKey;
    dts_SmtDte.DataID = encodeURI(uri);
    dts_SmtDte.reset();
    var strCbd = "";
    for (var i = 1; i <= dts_SmtDte.getTotalRow(); i++) {
        strCbd = strCbd + (strCbd == "" ? "" : ",") + dts_SmtDte.getCellData(i, "BZ_PROCS_NO") + "^" + dts_SmtDte.getCellData(i, "BILL_SUBMIT_DD_DISP");
    }
    cmb_BillSubmitDd.CBData = strCbd;
    cmb_BillSubmitDd.setSelectedIndex((strPar == "" ? 0 : cmb_BillSubmitDd.setSelectedIndex(cmb_BillSubmitDd.IndexOfColumn("BZ_PROCS_NO", strPar))));
    if (cmb_BillSubmitDd.getSelectedIndex() > -1) {
        scwin.fn_search(cmb_BillSubmitDd.BindColVal);
    } else {
        scwin.fn_search(""); // 화면초기화, 조건값을 ""로 조회하면 dts_Pub.CountRow는 0이 된다.

    }
};
scwin.fn_getUserId = function() {
    return js_emp_no;
};


// dialog 호출용 함수
// 예비심사청구제출기관 호출관련
scwin.fn_getParIsur = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = txb_IsurCd; // 코드값을 포함할 컨트롤
    arrPar[1] = txb_CoNm; // 명칭값을 포함할 컨트롤
    arrPar[2] = "KSQ_EXEM"; // 코스닥예비심사

    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};
scwin.fn_setParIsur = function(arrPar) {
    txb_IsurCd.setValue((arrPar.length >= 1 ? arrPar[0] : ""));
    txb_CoNm.setValue((arrPar.length >= 2 ? arrPar[1] : ""));
};


// 상세화면
