/*
	00443-재무통화ISO코드-일반사항-FNC_CURR_ISO_CD-cmb_CapCurrIsoCd
	*/
scwin.fn_searchCode = function() {
    var arrCid = [{
        cid: "CURR_ISO_CD",
        cnm: "cmb_NETINCM_CURR_ISO_CD"
    }];
    var objCod;
    var url = "/CodeAction.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listCodeValueNameM&inputMessageId=CODE_M_IN&outputMessageId=CODE_M_OUT" + "&CD_ID_M='CURR_ISO_CD'";
    dts_Cod.DataID = encodeURI(url);
    dts_Cod.reset();
    var strCbd = "",
        i, j;
    for (i = 0; i < arrCid.length; i++) {
        objCod = document.getElementById(arrCid[i].cnm);
        if (objCod == null) {
            $c.win.alert(arrCid[i].cnm);
        }
        strCbd = "";
        for (j = 1; j <= dts_Cod.getTotalRow(); j++) {
            if (dts_Cod.getCellData(j, "CD_ENG_NM") == arrCid[i].cid) {
                strCbd = strCbd + (strCbd == "" ? "" : ",") + dts_Cod.getCellData(j, "VALUE") + "^" + dts_Cod.getCellData(j, "TEXT");
            }
        }
        objCod.CBData = strCbd;
    }
};
scwin.fn_searchReqInf = function(strKey) {
    var uri = "/prelistingKosdaq.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=searchPubofrReqInf" + "&inputMessageId=PRELISTING_KOSDAQ_PUBOFR_INOUT" + "&outputMessageId=PRELISTING_KOSDAQ_PUBOFR_INOUT" + "&BZ_PROCS_NO=" + strKey;
    dts_ReqInf.DataID = encodeURI(uri);
    dts_ReqInf.reset();
};
scwin.fn_search = function(strKey) {
    // 업무처리번호가 키값이다. 발행기관에 올바르지않은 발행기관코드를 입력했을 경우 fn_searchSubmitDate를 통해서 ""이 인수로 전달된다.
    scwin.strKeyBzProcsNo = strKey;
    scwin.fn_searchReqInf(scwin.strKeyBzProcsNo);
    var uri = "/prelistingKosdaq.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=searchPubofr" + "&inputMessageId=PRELISTING_KOSDAQ_PUBOFR_INOUT" + "&outputMessageId=PRELISTING_KOSDAQ_PUBOFR_INOUT" + "&BZ_PROCS_NO=" + scwin.strKeyBzProcsNo;
    dts_Pub.DataID = encodeURI(uri);
    dts_Pub.reset();
};
scwin.fn_save = function() {
    if ($c.stf.getObjectValue(edt_NETINCM_AMT) == "") {
        $c.win.alert("[당기순이익(원화)]을 입력하세요");
        return;
    } {
        var s = "";
        for (i = 1; i <= dts_Pub.getTotalCol(); i++) {
            s = s + "\n" + dts_Pub.getColumnID(i - 1) + "," + dts_Pub.getCellData(1, i);
        }
        log.Text = log.Text + "\n" + s + "\n" + dts_Pub.Text;
        s = "";
        for (i = 1; i <= dts_ReqInf.getTotalCol(); i++) {
            s = s + "\n" + dts_ReqInf.getColumnID(i - 1) + "," + dts_ReqInf.getCellData(1, i);
        }
        log.Text = log.Text + "\n" + s + "\n" + dts_ReqInf.Text;
    }
    if ($c.cp.isModified(dts_Pub) || $c.cp.isModified(dts_ReqInf)) {
        // dts_ReqInf의 UseChangeInfo를 false로 지정하여 무조건 insert상태로 서버로 전송됨.
        dts_ReqInf.setCellData(1, "LST_PUBOFR_DTL_SAVE_EMP_NO", scwin.fn_getUserId());
        tr_Save.Action = "/prelistingKosdaq.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02 + "&method=savePubofr";
        tr_Save.KeyName = "toinb_dataid4";
        tr_Save.KeyValue = "JSP(I:pInpReqInf=dts_ReqInf, I:pInpPubofr=dts_Pub)";
        tr_Save.Post();
    } else {
        $c.win.alert(scwin.MGS_NO_UPDT);
    }
};
scwin.getCtrVal = function(s) {
    var o = document.getElementById(s);
    if (o != undefined) {
        var oval = o.getText();
        if (oval == "") {
            return 0;
        } else if (isNaN(oval)) {
            return 0;
        } else {
            return parseInt(oval);
        }
    } else {
        $c.win.alert("[" + s + "] is undefined");
        return 0;
    }
};
scwin.fn_wrtCalCtr = function(o) {
    var valTot = 0,
        arro, valTmp;
    var arr = [
        [
            ["med_BfpubofrCmstkShrs", "med_BfpubofrPrefstkShrs"], "med_BfpubofrShrs", "+"
        ],
        [
            ["med_PubofrCmstkShrs", "med_PubofrPrefstkShrs"], "med_PubofrShrs", "+"
        ],
        [
            ["med_ListCmstkShrs", "med_ListPrefstkShrs"], "med_ListShrs", "+"
        ],
        [
            ["med_PubofrShrs", "med_StatPubofrHopUplmtTotamt"], "med_StatPubofrSchdlUplmtTotamt", "*"
        ],
        [
            ["med_PubofrShrs", "med_StatPubofrHopLwlmtTotamt"], "med_StatPubofrSchdlLwlmtTotamt", "*"
        ],
        [
            ["med_PubofrShrs", "med_PubofrFinalPrc"], "med_PubofrFinalAmt", "*"
        ],
        [
            ["med_EmpstkAssgnShrs", "med_PubofrShrs"], "med_EmpstkAssgnRto", "/"
        ],
        [
            ["med_GenAssgnShrs", "med_PubofrShrs"], "med_GenAssgnRto", "/"
        ],
        [
            ["med_InstInvstAssgnShrs", "med_PubofrShrs"], "med_InstInvstAssgnRto", "/"
        ],
        [
            ["med_EmpstkAssgnShrs", "med_GenAssgnShrs", "med_InstInvstAssgnShrs"], "med_TotAssgnShrs", "+"
        ],
        [
            ["med_TotAssgnShrs", "med_PubofrShrs"], "med_TotAssgnRto", "/"
        ],
        [
            ["med_EmpstkSubsrCnt", "med_GenSubsrCnt", "med_InstInvstSubsrCnt"], "med_TotSubsrCnt", "+"
        ],
        [
            ["med_EmpstkSubsShrs", "med_GenSubsShrs", "med_InstInvstSubsShrs"], "med_TotSubsShrs", "+"
        ],
        [
            ["med_GenSubsShrs", "med_GenAssgnShrs"], "txb_GenCompteRt", ":"
        ],
        [
            ["med_ListAgnccomUdwrtShrs", "med_PubofrShrs"], "med_ListAgnccomUdwrtRto", "/"
        ]
    ];
    for (i = 0; i < arr.length; i++) {
        valCtr = 0;
        valTot = 0;
        if (arr[i][2] == "+") {
            for (j = 0; j < arr[i][0].length; j++) {
                valTot += scwin.getCtrVal(arr[i][0][j]);
            }
        } else if ((arr[i][2] == "/") || (arr[i][2] == ":")) {
            valTot = scwin.getCtrVal(arr[i][0][0]);
            for (j = 1; j < arr[i][0].length; j++) {
                try {
                    valTmp = scwin.getCtrVal(arr[i][0][j]);
                    valTot = (valTmp == 0 ? 0 : valTot / valTmp);
                } catch (err) {
                    $c.win.alert("[" + arr[i][0][j] + "] 합산처리 중  오류");
                }
            }
            if (arr[i][2] == "/") {
                valTot = valTot * 100;
            }
        } else if (arr[i][2] == "*") {
            valTot = 1;
            for (j = 0; j < arr[i][0].length; j++) {
                valTot *= scwin.getCtrVal(arr[i][0][j]);
            }
        }
        arro = document.getElementById(arr[i][1]);
        if (arro != undefined) {
            if (arro.id == "txb_GenCompteRt") {
                arro.setValue(valTot.toFixed(2) + ":1");
            } else {
                arro.setValue(valTot);
            }
        } else {
            $c.win.alert("[" + arr[i][0][j] + "] undefined");
        }
    }
};
scwin.fn_GetProvider = function() {
    var url = frame.srcUrl;
    var arr = url.split("?");
    return (arr.length >= 1 ? $c.frame.path("../" + arr[1]) : undefined);
};
scwin.fn_OpenDtl = async function() {
    scwin.fn_GetPar = fn_GetParDtl;
    scwin.fn_SetPar = undefined;
    if ($c.frame.path("/top") != undefined) {
        $c.frame.path("/top").WinOpen("DLG_PRECOM_DTL", "../lstproc/ULDSTF05004.gfm?" + frame.FrameID, "예비심사청구상세", 1055 + 5, 670 + 30);
    } else {
        await $c.frame.CreateFrame("DLG_PRECOM_DTL", "../lstproc/ULDSTF05004.gfm", "예비심사청구상세", 10, 10, 1055 + 5, 670 + 30, "window", 0, 0, false);
    }
};
