    return [txb_ExamprnEmpNm, med_BfpubofrShrs, med_PubofrShrs, med_ListShrs, med_StatPubofrSchdlUplmtTotamt, med_StatPubofrSchdlLwlmtTotamt, med_PubofrFinalAmt, med_ListAgnccomUdwrtRto, med_EmpstkAssgnRto, med_GenAssgnRto, med_InstInvstAssgnRto, med_TotAssgnShrs, med_TotAssgnRto, med_TotSubsrCnt, med_TotSubsShrs, txb_GenCompteRt, txb_LeadcomMbrNm1, txb_LeadcomMbrNm2];
};
