scwin.dts_Pub_OnLoadCompleted = function(rowcount) {
    var s = "";
    for (i = 1; i <= dts_Pub.getTotalCol(); i++) {
        s = s + "\n" + dts_Pub.getColumnID(i - 1) + ":" + dts_Pub.getCellData(1, i);
    }
    log.Text = log.Text + "\n" + s;
    if ((rowcount == 0) && (dts_ReqInf.getTotalRow() > 0)) {
        // 공모정보만 존재하지 않는 경우
        dts_Pub.insertRow();
        dts_Pub.setCellData(1, "BZ_PROCS_NO", scwin.strKeyBzProcsNo);
    }
    if ((rowcount == 0) && (dts_ReqInf.getTotalRow() == 0)) {
        scwin.fn_setPanReadOnlyPubOfr(); // 발못된 발행기관코드 조건값에 의해 조회 결과가 없는경우
        $c.win.alert($c.stf.getMessageParam("MSG-0003", ""));
    } else {
        scwin.fn_setPanWritablePubOfr();
    }
    scwin.fn_wrtCalCtr();
};
scwin.dts_ReqInf_OnLoadCompleted = function(rowcount) {
    var s = "";
