scwin.gform_onload = function() {
    log.style.width = 0;
    var arr = new Array();
    var pvd = scwin.fn_GetProvider();
    if (pvd != undefined) {
        scwin.fn_GetPar = pvd.scwin.fn_GetPar;
        scwin.fn_SetPar = pvd.scwin.fn_SetPar;
        frame.XPos = pvd.XPos + 100;
    }
    if (scwin.fn_GetPar != undefined) {
        scwin.fn_GetPar(arr);
    }
    /* 
    arr[0] = "03929";
    arr[1] = "920";
    arr[2] = "시험발행기관명";
    */

    txb_IsurCd.setValue((arr.length >= 1 ? arr[0] : ""));
    txb_CoNm.setValue((arr.length >= 3 ? arr[2] : "")); // 발행기관명도 넘겨받아 컨트롤에 반영해야 한다.

    if (arr.length > 2) {
        scwin.fn_searchSubmitDate(arr[0], arr[1]);
    } else {
        scwin.fn_setPanReadOnlyPubOfr();
    }
    $c.elw.fn_searchCode();
};
